/**
 * @name JWT validation bypass
 * @description Improper JWT validation could allow authentication bypass
 * @kind path-problem
 * @problem.severity error
 * @id py/jwt-validation-bypass
 * @tags security
 *        external/cwe/cwe-345
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module JwtValidationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for JWT decode/verify calls with untrusted input
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("google").getMember("auth").getMember("jwt").getMember(["decode", "verify"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module JwtValidationFlow = TaintTracking::Global<JwtValidationConfig>;
import JwtValidationFlow::PathGraph

from JwtValidationFlow::PathNode source, JwtValidationFlow::PathNode sink
where JwtValidationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "JWT validation with untrusted input from $@.", source.getNode(), "user input"

